<script setup>
import {ref,onMounted,reactive} from 'vue'
import {ops,perform,parse} from '../operations'
const rows=ref([]),profile=ref({}),error=ref(''),open=ref(false),model=reactive({}),policy=reactive({can_export:false,can_unmask:false,can_record:true}),policyUser=ref(null)
async function load(){try{profile.value=await ops('/me');rows.value=await ops('/teams')}catch(e){error.value=e.message}}
function edit(row){Object.keys(model).forEach(k=>delete model[k]);Object.assign(model,row?{...row,settings:parse(row.settings_json),members:row.members.map(m=>({user_id:m.user_id,is_lead:!!m.is_lead}))}:{name:'',enabled:true,settings:{after_call_seconds:0,queue_timeout_seconds:60,personal_override:false},members:[]});open.value=true}
async function loadPolicy(){if(!policyUser.value)return;try{const value=await ops('/permissions/'+policyUser.value);for(const k of ['can_export','can_unmask','can_record'])policy[k]=!!value[k]}catch(e){error.value=e.message}}
async function save(){const result=await perform(()=>ops('/teams','POST',model),load);if(result)open.value=false}
onMounted(load)
</script>
<template><PageHeader title="团队与数据权限" description="组长查看本组，坐席查看本人；服务端同步校验"><el-button type="primary" @click="edit()">新增坐席组</el-button></PageHeader><el-alert v-if="error" :title="error" type="error"/><el-card><DataGrid :rows="rows" :columns="[{key:'name',label:'组名'},{key:'enabled',label:'启用'},{key:'revision',label:'版本'},{key:'members',label:'成员',render:v=>(v||[]).map(m=>m.full_name+(m.is_lead?'（组长）':'')).join('、')}]"><template #actions="{row}"><el-button link @click="edit(row)">编辑坐席组</el-button></template></DataGrid></el-card><el-card header="用户操作权限"><el-select v-model="policyUser" aria-label="权限用户" @change="loadPolicy"><el-option v-for="u in profile.users||[]" :key="u.id" :value="u.id" :label="u.full_name"/></el-select><el-checkbox v-model="policy.can_export">允许导出</el-checkbox><el-checkbox v-model="policy.can_unmask">显示完整号码</el-checkbox><el-checkbox v-model="policy.can_record">访问录音</el-checkbox><el-button :disabled="!policyUser" @click="perform(()=>ops('/permissions/'+policyUser,'PUT',policy),loadPolicy)">保存操作权限</el-button><p>管理员保留全租户管理权限。组长在成员表中设置，数据范围实时生效；普通坐席导出默认关闭，号码默认脱敏。</p></el-card><el-dialog v-model="open" title="坐席组配置" width="760px"><el-form label-position="top"><el-form-item label="组名"><el-input v-model="model.name" aria-label="坐席组名"/></el-form-item><el-form-item label="启用"><el-switch v-model="model.enabled" aria-label="启用坐席组"/></el-form-item><el-form-item label="成员"><el-select :model-value="(model.members||[]).map(m=>m.user_id)" multiple aria-label="坐席组成员" @change="model.members=$event.map(id=>model.members.find(m=>m.user_id===id)||{user_id:id,is_lead:false})"><el-option v-for="u in profile.users||[]" :key="u.id" :value="u.id" :label="u.full_name" :disabled="!u.enabled"/></el-select></el-form-item><div v-for="m in model.members||[]" :key="m.user_id" class="toolbar"><span>{{profile.users?.find(u=>u.id===m.user_id)?.full_name}}</span><el-checkbox v-model="m.is_lead">组长</el-checkbox></div><template v-if="model.settings"><el-form-item label="通话后整理秒数"><el-input-number v-model="model.settings.after_call_seconds" :min="0" :max="600" aria-label="组整理秒数"/></el-form-item><el-form-item label="转接等待秒数"><el-input-number v-model="model.settings.queue_timeout_seconds" :min="5" :max="600" aria-label="组转接等待秒数"/></el-form-item><el-form-item label="允许个人覆盖"><el-switch v-model="model.settings.personal_override" aria-label="允许个人坐席设置"/></el-form-item></template><el-button type="primary" :disabled="!model.name" @click="save">保存坐席组</el-button></el-form></el-dialog></template>
